/**
 * 2026 국정감사 피감기관 색인 — 허브의 "기관명으로 감사일 찾기"가 쓴다.
 *
 * 원칙(2026-09-28 codex 검토):
 * - audit-2026.ts의 days.detail 문자열을 런타임에 쪼개지 않는다. 축약 표기("서울동부·남부·북부·서부지방검찰청")와
 *   "종합감사" 같은 비기관 항목이 섞여 기관명이 틀어진다. 이 파일은 위원회 국정감사계획서 원문과 대조해 만든다.
 * - 한 기관이 여러 날 감사받으면 날짜별 레코드를 따로 둔다(기관감사·종합감사·현장시찰).
 * - 계획서가 확인된 위원회만 싣는다. 보도 일정(reported) 위원회는 검색 결과 없음 대신 "계획서 확인 전"으로 안내한다.
 * - 기관별 정적 페이지는 만들지 않는다(얇은 페이지 대량 생성 = AdSense 저가치 콘텐츠 위험).
 */

export interface AuditAgencyRecord {
  /** 계획서의 정식 기관명 */
  agency: string;
  /** 검색용 약칭(LH, 과기정통부 등) */
  aliases?: string[];
  /** 위원회 정식 명칭(audit-2026.ts committees[].name과 같다) */
  committee: string;
  /** "10-07" — 기간만 있는 경우(재외공관 반별 감사) 시작일 */
  date: string;
  /** 계획서에 개별 감사일 없이 기간만 있을 때 종료일 */
  dateEnd?: string;
  time?: string;
  place?: string;
  type: "기관감사" | "종합감사" | "현장시찰";
  note?: string;
  sourceUrl?: string;
}

